import { http, HttpResponse } from "msw/http"
import { describe, expect, it } from "vitest"

import { siteConfig } from "@/config/site.config"

import { addUser } from "@/features/users/api/add-user.api"
import { USERS_PATH } from "@/features/users/constants/users.constants"
import { server } from "@/test/server"

const ADD_USER_URL = `${siteConfig.apiUrl}${USERS_PATH}/add`
const input = {
  firstName: "Ada",
  lastName: "Lovelace",
  username: "ada.lovelace",
  title: "Mathematician",
  department: "Research",
  role: "user" as const
}
const created = {
  firstName: "Ada",
  lastName: "Lovelace",
  username: "ada.lovelace",
  role: "user",
  company: { title: "Mathematician", department: "Research" }
}

describe("addUser", () => {
  it("posts the position and department under company and returns the created user", async () => {
    let body: unknown
    server.use(
      http.post(ADD_USER_URL, async ({ request }) => {
        body = await request.json()
        return HttpResponse.json({ id: 209, ...created }, { status: 201 })
      })
    )

    await expect(addUser(input)).resolves.toEqual({ id: 209, ...created })
    expect(body).toEqual(created)
  })
})

import { api } from "@/lib/api"

import { USERS_PATH } from "@/features/users/constants/users.constants"
import { toUserBody } from "@/features/users/helpers/to-user-body"
import { userSchema } from "@/features/users/schemas/user.schema"
import type { User, UserFormInput } from "@/features/users/schemas/user.schema"

/** DummyJSON answers as if the user was created, but it does not store it. */
export function addUser(input: UserFormInput, signal?: AbortSignal): Promise<User> {
  return api.post(`${USERS_PATH}/add`, toUserBody(input), { schema: userSchema, signal })
}

import { api } from "@/lib/api"

